<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Package, Boxes, TriangleAlert, PackageX, Plus, ArrowUpRight, ArrowDownLeft, ArrowRight, ChevronLeft, ChevronRight, Search, SlidersHorizontal, Download, Upload, RotateCcw, Trash2, Pencil, Archive, FolderOpen, CalendarDays, ChevronDown, ArrowDown, ArrowUp, Printer, Database, ShieldCheck, HardDrive, X, ArrowLeftRight } from 'lucide-vue-next'
import Modal from './Modal.vue'
import { state, activeProducts, save, notify } from '../store'
import { addMovement, emptyInventory, parseBackup, today, saveProduct, saveCategory, deleteCategory as removeCategory, toggleArchive, type Product } from '../domain/inventory'
import { createSeed } from '../data/seed'
const props=defineProps<{page:string}>()
const search=ref(''), categoryFilter=ref(''), statusFilter=ref(''), sort=ref('name'), currentPage=ref(1), period=ref('30'), start=ref(''),end=ref(''), reportTab=ref('stock')
const modal=ref<''|'product'|'category'|'movement'|'confirm'>(''), formError=ref(''), editing=ref('')
const confirmTitle=ref(''), confirmText=ref('');let confirmAction:()=>Promise<void>
const form=ref({code:'',name:'',categoryId:'',unit:'pcs',cost:'',minimum:5,initial:0})
const categoryForm=ref({name:'',color:'#299e8c'})
const movementForm=ref({productId:'',type:'in' as 'in'|'out',quantity:1,date:today(),note:''})
const dateLabel=computed(()=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric'}).format(new Date()))
const low=computed(()=>activeProducts.value.filter(p=>p.stock>0&&p.stock<=p.minimum))
const out=computed(()=>activeProducts.value.filter(p=>p.stock===0))
const stockTotal=computed(()=>activeProducts.value.reduce((n,p)=>n+p.stock,0))
const money=(n:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n)
const number=(n:number)=>new Intl.NumberFormat('id-ID').format(n)
const categoryName=(id:string)=>state.data.categories.find(c=>c.id===id)?.name||'—'
const categoryColor=(id:string)=>state.data.categories.find(c=>c.id===id)?.color||'#87918e'
const productName=(id:string)=>state.data.products.find(p=>p.id===id)?.name||'Barang dihapus'
const productCode=(id:string)=>state.data.products.find(p=>p.id===id)?.code||'—'
const status=(p:Product)=>p.archived?'Diarsipkan':p.stock===0?'Habis':p.stock<=p.minimum?'Stok rendah':'Tersedia'
const statusClass=(p:Product)=>p.archived?'neutral':p.stock===0?'danger':p.stock<=p.minimum?'warning':'success'
const filteredProducts=computed(()=>state.data.products.filter(p=>(statusFilter.value==='archived'?p.archived:!p.archived)&&`${p.name} ${p.code}`.toLowerCase().includes(search.value.toLowerCase())&&(!categoryFilter.value||p.categoryId===categoryFilter.value)&&(!statusFilter.value||statusFilter.value==='archived'||(statusFilter.value==='low'&&p.stock>0&&p.stock<=p.minimum)||(statusFilter.value==='out'&&p.stock===0)||(statusFilter.value==='available'&&p.stock>p.minimum))).sort((a,b)=>sort.value==='stock'?a.stock-b.stock:sort.value==='code'?a.code.localeCompare(b.code):a.name.localeCompare(b.name)))
const pagedProducts=computed(()=>filteredProducts.value.slice((currentPage.value-1)*8,currentPage.value*8))
const sortedMovements=computed(()=>[...state.data.movements].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)))
const filteredMovements=computed(()=>sortedMovements.value.filter(m=>(!start.value||m.date>=start.value)&&(!end.value||m.date<=end.value)&&(!search.value||`${productName(m.productId)} ${productCode(m.productId)} ${m.note}`.toLowerCase().includes(search.value.toLowerCase()))&&(!statusFilter.value||m.type===statusFilter.value)))
const pagedMovements=computed(()=>filteredMovements.value.slice((currentPage.value-1)*10,currentPage.value*10))
const recent=computed(()=>sortedMovements.value.slice(0,5))
const chart=computed(()=>{
 const days=Number(period.value), points=[]; const interval=days===7?1:5
 for(let i=days-1;i>=0;i-=interval){const d=new Date(`${today()}T12:00:00`);d.setDate(d.getDate()-i);const stop=new Date(d);stop.setDate(stop.getDate()+interval);const date=d.toLocaleDateString('sv-SE'),to=stop.toLocaleDateString('sv-SE');const rows=state.data.movements.filter(m=>m.date>=date&&m.date<to);points.push({label:d.toLocaleDateString('id-ID',{day:'numeric',month:'short'}),incoming:rows.filter(m=>m.type==='in').reduce((s,m)=>s+m.quantity,0),outgoing:rows.filter(m=>m.type==='out').reduce((s,m)=>s+m.quantity,0)})}return points
})
const chartMax=computed(()=>Math.max(10,...chart.value.flatMap(x=>[x.incoming,x.outgoing])))
const chartTotals=computed(()=>({incoming:chart.value.reduce((s,x)=>s+x.incoming,0),outgoing:chart.value.reduce((s,x)=>s+x.outgoing,0)}))
const stockValue=computed(()=>activeProducts.value.reduce((s,p)=>s+(p.cost||0)*p.stock,0))
watch(()=>props.page,()=>{search.value='';categoryFilter.value='';statusFilter.value='';currentPage.value=1;formError.value='';start.value='';end.value=''})
watch([search,categoryFilter,statusFilter,sort,start,end],()=>currentPage.value=1)
function openProduct(p?:Product) {editing.value=p?.id||'';form.value=p?{code:p.code,name:p.name,categoryId:p.categoryId,unit:p.unit,cost:p.cost===null?'':String(p.cost),minimum:p.minimum,initial:0}:{code:'',name:'',categoryId:state.data.categories[0]?.id||'',unit:'pcs',cost:'',minimum:5,initial:0};formError.value='';modal.value='product'}
function openCategory(c?:{id:string;name:string;color:string}) {editing.value=c?.id||'';categoryForm.value={name:c?.name||'',color:c?.color||'#299e8c'};formError.value='';modal.value='category'}
function openMovement(type:'in'|'out'='in',productId='') {movementForm.value={productId:productId||activeProducts.value[0]?.id||'',type,quantity:1,date:today(),note:''};formError.value='';modal.value='movement'}
async function submitProduct() {await attempt(async()=>{await save(d=>saveProduct(d,form.value,editing.value),editing.value?'Barang berhasil diperbarui':'Barang baru berhasil ditambahkan')})}
async function submitCategory() {await attempt(async()=>{await save(d=>saveCategory(d,categoryForm.value,editing.value))})}
async function submitMovement(){await attempt(async()=>{await save(d=>addMovement(d,movementForm.value),'Transaksi stok berhasil dicatat')})}
async function attempt(action:()=>Promise<void>){formError.value='';try{await action();modal.value=''}catch(e){formError.value=e instanceof Error?e.message:'Terjadi kesalahan.'}}
function confirm(title:string,text:string,action:()=>Promise<void>){confirmTitle.value=title;confirmText.value=text;confirmAction=action;formError.value='';modal.value='confirm'}
function archiveProduct(p:Product){confirm(p.archived?'Aktifkan kembali barang?':'Arsipkan barang?',p.archived?'Barang akan kembali tersedia untuk transaksi.':'Barang disembunyikan dari inventaris aktif. Seluruh histori transaksi tetap tersimpan.',()=>save(d=>toggleArchive(d,p.id),p.archived?'Barang berhasil diaktifkan':'Barang berhasil diarsipkan'))}
function deleteCategory(categoryId:string){confirm('Hapus kategori?','Kategori hanya dapat dihapus jika tidak digunakan barang, termasuk barang yang diarsipkan.',()=>save(d=>removeCategory(d,categoryId),'Kategori berhasil dihapus'))}
function download(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v:unknown){let text=String(v??'');if(/^[\s]*[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
function exportCSV(kind:'stock'|'movements'='stock'){const rows=kind==='stock'?[['Kode','Nama','Kategori','Stok','Satuan','Minimum','Harga modal','Status'],...filteredProducts.value.map(p=>[p.code,p.name,categoryName(p.categoryId),p.stock,p.unit,p.minimum,p.cost,status(p)])]:[['Tanggal','ID transaksi','Kode','Barang','Jenis','Jumlah','Catatan'],...filteredMovements.value.map(m=>[m.date,m.id,productCode(m.productId),productName(m.productId),m.type==='in'?'Masuk':'Keluar',m.quantity,m.note])];download('\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),`inventra-${kind}-${today()}.csv`,'text/csv;charset=utf-8');notify('CSV berhasil diekspor')}
async function importBackup(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Ukuran backup maksimal 10 MB.');const data=parseBackup(JSON.parse(await file.text()));confirm('Ganti data dengan backup?',`Backup berisi ${data.products.length} barang, ${data.categories.length} kategori, dan ${data.movements.length} transaksi. Seluruh data saat ini akan diganti.`,()=>save(()=>data,'Backup berhasil dipulihkan'))}catch(e){notify(e instanceof Error?e.message:'Backup tidak valid.')}finally{input.value=''}}
function reset(clear=false){confirm(clear?'Hapus seluruh data lokal?':'Reset ke data contoh?',clear?'Semua barang, kategori, dan transaksi akan dihapus permanen dari browser ini. Ekspor backup terlebih dahulu.':'Seluruh data saat ini akan diganti dengan data fiktif awal. Ekspor backup jika ingin menyimpannya.',()=>save(()=>clear?emptyInventory():createSeed(),clear?'Data lokal berhasil dihapus':'Data contoh berhasil dipulihkan'))}
const printReport=()=>window.print()
</script>

<template>
<div class="workspace-content">
  <template v-if="page==='dashboard'">
    <div class="page-heading"><div><div class="eyebrow">INVENTORY OVERVIEW</div><h1>Semua stok, dalam kendali<span class="heading-dot">.</span></h1><p>Pantau persediaan dan aktivitas bisnis Anda dalam satu tempat.</p></div><div class="heading-actions"><span class="date-display"><CalendarDays :size="15"/>{{ dateLabel }}</span><button class="button primary" @click="openMovement()"><Plus :size="17"/>Catat Transaksi</button></div></div>
    <div class="stats-grid">
      <div class="stat-card"><div class="stat-top"><span>Total Jenis Barang</span><span class="stat-icon mint"><Package :size="20"/></span></div><div class="stat-value">{{number(activeProducts.length)}}<span>jenis barang</span></div><div class="stat-bottom"><span class="tiny-dot green"></span> Inventaris aktif <RouterLink to="/barang"><ArrowUpRight :size="16"/></RouterLink></div></div>
      <div class="stat-card"><div class="stat-top"><span>Total Unit Stok</span><span class="stat-icon blue"><Boxes :size="20"/></span></div><div class="stat-value">{{number(stockTotal)}}<span>unit tersedia</span></div><div class="stat-bottom"><span class="tiny-dot blue-dot"></span> Seluruh kategori <RouterLink to="/laporan"><ArrowUpRight :size="16"/></RouterLink></div></div>
      <div class="stat-card"><div class="stat-top"><span>Barang Stok Rendah</span><span class="stat-icon amber"><TriangleAlert :size="20"/></span></div><div class="stat-value">{{number(low.length)}}<span>perlu restock</span></div><div class="stat-bottom"><span class="tiny-dot orange"></span> Di bawah atau setara minimum <RouterLink to="/barang"><ArrowUpRight :size="16"/></RouterLink></div></div>
      <div class="stat-card"><div class="stat-top"><span>Barang Habis</span><span class="stat-icon red"><PackageX :size="20"/></span></div><div class="stat-value">{{number(out.length)}}<span>stok kosong</span></div><div class="stat-bottom"><span class="tiny-dot red-dot"></span> Perlu perhatian Anda <RouterLink to="/barang"><ArrowUpRight :size="16"/></RouterLink></div></div>
    </div>
    <div class="dashboard-middle">
      <section class="panel chart-panel"><div class="panel-heading"><div><h2>Arus pergerakan stok</h2><p>Ringkasan barang masuk dan keluar</p></div><label class="select-small"><CalendarDays :size="14"/><select v-model="period" aria-label="Periode grafik"><option value="30">30 hari terakhir</option><option value="7">7 hari terakhir</option></select></label></div><div class="chart-summary"><div><span class="legend-dot incoming"></span><span>Stok masuk</span><strong>{{number(chartTotals.incoming)}} <small>unit</small></strong></div><div><span class="legend-dot outgoing"></span><span>Stok keluar</span><strong>{{number(chartTotals.outgoing)}} <small>unit</small></strong></div><div class="chart-caption">Jumlah unit / periode</div></div><div class="bar-chart" role="img" :aria-label="`Grafik ${period} hari: ${chartTotals.incoming} unit masuk dan ${chartTotals.outgoing} unit keluar`"><div class="chart-axis"><span v-for="i in [4,3,2,1,0]" :key="i">{{Math.ceil(chartMax*i/4)}}</span></div><div class="plot"><div class="grid-lines"><i v-for="i in 5" :key="i"></i></div><div class="bar-groups"><div v-for="point in chart" :key="point.label" class="bar-group"><div class="bar-pair"><div class="bar in" :style="{height:Math.max(point.incoming/chartMax*100,point.incoming?2:0)+'%'}" :title="`${point.label}: ${point.incoming} masuk`"></div><div class="bar out" :style="{height:Math.max(point.outgoing/chartMax*100,point.outgoing?2:0)+'%'}" :title="`${point.label}: ${point.outgoing} keluar`"></div></div><span>{{point.label}}</span></div></div></div></div></section>
      <section class="panel attention-panel"><div class="panel-heading"><div><h2>Perlu perhatian</h2><p>Jaga stok tetap tersedia</p></div><span class="count-badge">{{low.length+out.length}}</span></div><div v-if="!low.length&&!out.length" class="empty-compact"><ShieldCheck :size="28"/><p>Semua stok dalam kondisi aman.</p></div><div v-for="p in [...out,...low].slice(0,4)" :key="p.id" class="attention-item"><span class="product-symbol" :style="{background:categoryColor(p.categoryId)+'15',color:categoryColor(p.categoryId)}"><Package :size="19"/></span><div><strong>{{p.name}}</strong><small>Min. {{p.minimum}} {{p.unit}}</small></div><span class="attention-stock" :class="p.stock===0?'text-red':'text-amber'">{{p.stock}}<small>{{p.unit}}</small></span></div><RouterLink to="/barang" class="panel-bottom-link">Lihat semua barang <ArrowRight :size="15"/></RouterLink></section>
    </div>
    <section class="panel recent-panel"><div class="panel-heading"><div><h2>Aktivitas terbaru</h2><p>Setiap pergerakan, tercatat dengan rapi.</p></div><RouterLink to="/transaksi" class="text-link">Semua transaksi <ArrowUpRight :size="15"/></RouterLink></div><div class="table-wrap"><table><thead><tr><th>BARANG</th><th>JENIS TRANSAKSI</th><th>JUMLAH</th><th>TANGGAL</th><th>CATATAN</th></tr></thead><tbody><tr v-for="m in recent" :key="m.id"><td><div class="product-cell"><span class="product-symbol"><Package :size="17"/></span><span><strong>{{productName(m.productId)}}</strong><small>{{productCode(m.productId)}}</small></span></div></td><td><span class="badge" :class="m.type==='in'?'success':'blue-badge'"><ArrowDownLeft v-if="m.type==='in'" :size="13"/><ArrowUpRight v-else :size="13"/>Stok {{m.type==='in'?'masuk':'keluar'}}</span></td><td class="quantity" :class="m.type==='in'?'text-green':''">{{m.type==='in'?'+':'−'}}{{m.quantity}} <small>{{state.data.products.find(p=>p.id===m.productId)?.unit}}</small></td><td>{{new Date(m.date+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}}</td><td class="muted note-cell">{{m.note||'—'}}</td></tr><tr v-if="!recent.length"><td colspan="5" class="empty-cell">Belum ada transaksi. Catat pergerakan stok pertama Anda.</td></tr></tbody></table></div></section>
    <div class="local-notice"><span class="notice-icon"><HardDrive :size="19"/></span><div><strong>Workspace demo, kebebasan untuk mencoba.</strong><p>Data fiktif tersimpan hanya di browser ini. Tidak ada data yang dikirim ke server.</p></div><RouterLink to="/pengaturan">Tentang demo <ArrowRight :size="15"/></RouterLink></div>
  </template>

  <template v-if="page==='barang'">
    <div class="page-heading"><div><div class="eyebrow">YOUR INVENTORY</div><h1>Manajemen Barang<span class="heading-dot">.</span></h1><p>Inventaris yang tertata, operasional yang lebih lancar.</p></div><div class="heading-actions"><button class="button" @click="exportCSV()"><Download :size="16"/>Ekspor CSV</button><button class="button primary" @click="openProduct()"><Plus :size="17"/>Tambah Barang</button></div></div>
    <div class="inventory-summary"><span><span class="tiny-dot green"></span><strong>{{activeProducts.length}}</strong> barang aktif</span><span><span class="tiny-dot orange"></span><strong>{{low.length}}</strong> stok rendah</span><span><span class="tiny-dot red-dot"></span><strong>{{out.length}}</strong> barang habis</span></div>
    <section class="panel"><div class="table-toolbar"><div class="search-input"><Search :size="17"/><input v-model="search" placeholder="Cari nama atau kode barang…" aria-label="Cari barang"/></div><div class="toolbar-controls"><select v-model="categoryFilter" aria-label="Filter kategori"><option value="">Semua kategori</option><option v-for="c in state.data.categories" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="statusFilter" aria-label="Filter status"><option value="">Semua status</option><option value="available">Tersedia</option><option value="low">Stok rendah</option><option value="out">Habis</option><option value="archived">Diarsipkan</option></select><select v-model="sort" aria-label="Urutkan barang"><option value="name">Nama A–Z</option><option value="code">Kode A–Z</option><option value="stock">Stok terendah</option></select></div></div><div class="table-wrap"><table><thead><tr><th>BARANG</th><th>KATEGORI</th><th>STOK</th><th>MIN. STOK</th><th>HARGA MODAL</th><th>STATUS</th><th class="align-right">AKSI</th></tr></thead><tbody><tr v-for="p in pagedProducts" :key="p.id"><td><div class="product-cell"><span class="product-symbol" :style="{color:categoryColor(p.categoryId),background:categoryColor(p.categoryId)+'12'}"><Package :size="19"/></span><span><strong>{{p.name}}</strong><small>{{p.code}}</small></span></div></td><td><span class="category-dot" :style="{background:categoryColor(p.categoryId)}"></span>{{categoryName(p.categoryId)}}</td><td><strong class="stock-number">{{p.stock}}</strong> <span class="muted">{{p.unit}}</span></td><td>{{p.minimum}} <span class="muted">{{p.unit}}</span></td><td>{{p.cost===null?'—':money(p.cost)}}</td><td><span class="badge" :class="statusClass(p)"><span class="badge-dot"></span>{{status(p)}}</span></td><td><div class="row-actions"><button class="icon-button" :aria-label="'Edit '+p.name" title="Edit barang" @click="openProduct(p)"><Pencil :size="15"/></button><button class="icon-button" :aria-label="(p.archived?'Aktifkan ':'Arsipkan ')+p.name" :title="p.archived?'Aktifkan barang':'Arsipkan barang'" @click="archiveProduct(p)"><RotateCcw v-if="p.archived" :size="15"/><Archive v-else :size="15"/></button></div></td></tr><tr v-if="!pagedProducts.length"><td colspan="7"><div class="empty-state"><Package :size="34"/><h3>Tidak ada barang ditemukan</h3><p>Ubah filter atau tambahkan barang baru untuk memulai.</p><button class="button primary" @click="openProduct()"><Plus :size="16"/>Tambah Barang</button></div></td></tr></tbody></table></div><div class="pagination"><span>Menampilkan {{filteredProducts.length?((currentPage-1)*8+1):0}}–{{Math.min(currentPage*8,filteredProducts.length)}} dari {{filteredProducts.length}} barang</span><div><button class="button small" :disabled="currentPage===1" aria-label="Halaman sebelumnya" @click="currentPage--"><ChevronLeft :size="15"/></button><span>{{currentPage}} / {{Math.max(1,Math.ceil(filteredProducts.length/8))}}</span><button class="button small" :disabled="currentPage*8>=filteredProducts.length" aria-label="Halaman berikutnya" @click="currentPage++"><ChevronRight :size="15"/></button></div></div></section>
  </template>

  <template v-if="page==='kategori'">
    <div class="page-heading"><div><div class="eyebrow">ORGANIZE YOUR INVENTORY</div><h1>Kategori Barang<span class="heading-dot">.</span></h1><p>Kelompokkan barang agar selalu mudah ditemukan.</p></div><button class="button primary" @click="openCategory()"><Plus :size="17"/>Tambah Kategori</button></div>
    <div class="category-grid"><section v-for="c in state.data.categories" :key="c.id" class="panel category-card"><div class="category-card-top"><span class="category-icon" :style="{color:c.color,background:c.color+'14'}"><FolderOpen :size="26"/></span><div class="row-actions"><button class="icon-button" :aria-label="'Edit kategori '+c.name" @click="openCategory(c)"><Pencil :size="16"/></button><button class="icon-button" :aria-label="'Hapus kategori '+c.name" @click="deleteCategory(c.id)"><Trash2 :size="16"/></button></div></div><h2>{{c.name}}</h2><p>{{activeProducts.filter(p=>p.categoryId===c.id).length}} barang aktif</p><div class="category-card-foot"><span>{{number(activeProducts.filter(p=>p.categoryId===c.id).reduce((s,p)=>s+p.stock,0))}} total unit</span><ArrowUpRight :size="17"/></div></section></div><div v-if="!state.data.categories.length" class="panel empty-state"><FolderOpen :size="36"/><h3>Mulai dengan sebuah kategori</h3><p>Buat kategori sebelum menambahkan barang.</p><button class="button primary" @click="openCategory()">Tambah Kategori</button></div>
  </template>

  <template v-if="page==='transaksi'">
    <div class="page-heading"><div><div class="eyebrow">STOCK MOVEMENTS</div><h1>Transaksi Stok<span class="heading-dot">.</span></h1><p>Catat setiap pergerakan. Jaga setiap unit tetap terlacak.</p></div><div class="heading-actions"><button class="button" @click="openMovement('out')"><ArrowUpRight :size="17"/>Stok Keluar</button><button class="button primary" @click="openMovement('in')"><ArrowDownLeft :size="17"/>Stok Masuk</button></div></div>
    <div class="info-strip"><ShieldCheck :size="18"/><span>Histori bersifat permanen untuk menjaga konsistensi stok. Gunakan transaksi baru untuk mencatat koreksi.</span></div>
  </template>

  <template v-if="page==='laporan'">
    <div class="page-heading"><div><div class="eyebrow">INSIGHTS & REPORTS</div><h1>Laporan Inventaris<span class="heading-dot">.</span></h1><p>Data yang jelas untuk keputusan yang lebih baik.</p></div><div class="heading-actions no-print"><button class="button" @click="printReport"><Printer :size="16"/>Cetak</button><button class="button primary" @click="exportCSV(reportTab==='stock'?'stock':'movements')"><Download :size="16"/>Ekspor CSV</button></div></div>
    <div class="report-summary"><div class="panel"><span>Nilai persediaan aktif saat ini</span><strong>{{money(stockValue)}}</strong><small>Berdasarkan harga modal yang tersedia</small></div><div class="panel"><span>Total stok aktif saat ini</span><strong>{{number(stockTotal)}} <small>unit</small></strong><small>Dari {{activeProducts.length}} jenis barang</small></div><div class="panel"><span>Transaksi pada rentang terpilih</span><strong>{{filteredMovements.length}} <small>transaksi</small></strong><small>Masuk {{filteredMovements.filter(m=>m.type==='in').reduce((s,m)=>s+m.quantity,0)}} · Keluar {{filteredMovements.filter(m=>m.type==='out').reduce((s,m)=>s+m.quantity,0)}} unit</small></div></div>
    <div class="tabs no-print"><button :class="{active:reportTab==='stock'}" @click="reportTab='stock';search='';statusFilter=''">Ringkasan Stok</button><button :class="{active:reportTab==='movements'}" @click="reportTab='movements';search='';statusFilter=''">Riwayat Mutasi</button></div>
    <section v-if="reportTab==='stock'" class="panel"><div class="panel-heading"><div><h2>Ringkasan stok terkini</h2><p>Saldo saat ini · {{dateLabel}} · Seluruh barang aktif</p></div></div><div class="table-wrap"><table><thead><tr><th>KODE</th><th>NAMA BARANG</th><th>KATEGORI</th><th>STOK</th><th>NILAI STOK</th><th>STATUS</th></tr></thead><tbody><tr v-for="p in activeProducts" :key="p.id"><td class="code">{{p.code}}</td><td><strong>{{p.name}}</strong></td><td>{{categoryName(p.categoryId)}}</td><td>{{p.stock}} {{p.unit}}</td><td>{{p.cost===null?'—':money(p.stock*p.cost)}}</td><td><span class="badge" :class="statusClass(p)">{{status(p)}}</span></td></tr><tr v-if="!activeProducts.length"><td colspan="6" class="empty-cell">Belum ada barang aktif untuk dilaporkan.</td></tr></tbody></table></div></section>
  </template>

  <section v-if="page==='transaksi'||(page==='laporan'&&reportTab==='movements')" class="panel"><div class="table-toolbar"><div class="search-input"><Search :size="17"/><input v-model="search" aria-label="Cari transaksi" placeholder="Cari barang atau catatan…"/></div><div class="toolbar-controls date-filters"><label>Dari<input v-model="start" type="date" aria-label="Tanggal mulai" :max="end||today()"/></label><label>Sampai<input v-model="end" type="date" aria-label="Tanggal akhir" :min="start" :max="today()"/></label><select v-model="statusFilter" aria-label="Jenis transaksi"><option value="">Semua jenis</option><option value="in">Stok masuk</option><option value="out">Stok keluar</option></select></div></div><p v-if="start&&end&&start>end" class="form-error">Rentang tanggal tidak valid.</p><div class="table-wrap"><table><thead><tr><th>TANGGAL / ID</th><th>BARANG</th><th>JENIS</th><th>JUMLAH</th><th>CATATAN</th></tr></thead><tbody><tr v-for="m in (page==='laporan'?filteredMovements:pagedMovements)" :key="m.id"><td><div class="stack"><span>{{new Date(m.date+'T12:00:00').toLocaleDateString('id-ID')}}</span><small class="code" :title="m.id">{{m.id.slice(0,13)}}</small></div></td><td><div class="stack"><strong>{{productName(m.productId)}}</strong><small>{{productCode(m.productId)}}</small></div></td><td><span class="badge" :class="m.type==='in'?'success':'blue-badge'"><ArrowDownLeft v-if="m.type==='in'" :size="13"/><ArrowUpRight v-else :size="13"/>Stok {{m.type==='in'?'masuk':'keluar'}}</span></td><td class="quantity" :class="{'text-green':m.type==='in'}">{{m.type==='in'?'+':'−'}}{{m.quantity}}</td><td class="note-cell">{{m.note||'—'}}</td></tr><tr v-if="!filteredMovements.length"><td colspan="5" class="empty-cell">Tidak ada transaksi pada filter ini.</td></tr></tbody></table></div><div v-if="page==='transaksi'" class="pagination"><span>{{filteredMovements.length}} transaksi · Halaman {{currentPage}} dari {{Math.max(1,Math.ceil(filteredMovements.length/10))}}</span><div><button class="button small" :disabled="currentPage===1" aria-label="Halaman sebelumnya" @click="currentPage--"><ChevronLeft :size="16"/></button><button class="button small" :disabled="currentPage*10>=filteredMovements.length" aria-label="Halaman berikutnya" @click="currentPage++"><ChevronRight :size="16"/></button></div></div></section>

  <template v-if="page==='pengaturan'">
    <div class="page-heading"><div><div class="eyebrow">YOUR DEMO WORKSPACE</div><h1>Pengaturan Demo<span class="heading-dot">.</span></h1><p>Kelola data lokal Anda dengan mudah dan transparan.</p></div><span class="demo-pill"><span></span> Mode demonstrasi</span></div>
    <div class="settings-layout"><section class="panel settings-panel"><div class="settings-icon mint"><HardDrive :size="24"/></div><h2>Data Anda, di browser Anda.</h2><p>INVENTRA merupakan demo portofolio dengan data fiktif. Semua perubahan disimpan di IndexedDB pada browser dan perangkat ini, tanpa backend, akun, atau sinkronisasi cloud.</p><div class="settings-facts"><span><ShieldCheck :size="17"/>Tidak meminta password atau data sensitif</span><span><Database :size="17"/>{{state.data.products.length}} barang · {{state.data.categories.length}} kategori · {{state.data.movements.length}} transaksi</span><span><HardDrive :size="17"/>Menghapus data situs di browser juga menghapus inventaris</span></div><p class="muted">Jangan masukkan informasi pribadi atau rahasia. Mode privat, pembersihan browser, atau keterbatasan ruang penyimpanan dapat menghapus data. Simpan backup secara berkala.</p></section><div class="settings-actions"><section class="panel settings-panel"><h2>Backup & pemulihan</h2><p>Unduh seluruh inventaris dan histori transaksi, atau pulihkan backup JSON yang valid. Impor akan mengganti data saat ini.</p><div class="heading-actions"><button class="button" @click="download(JSON.stringify(state.data,null,2),'inventra-backup-'+today()+'.json','application/json');notify('Backup JSON berhasil diekspor')"><Download :size="16"/>Ekspor Backup</button><label class="button upload-button"><Upload :size="16"/>Impor JSON<input type="file" accept=".json,application/json" aria-label="Impor backup JSON" @change="importBackup"/></label></div></section><section class="panel settings-panel"><h2>Mulai dari awal</h2><p>Pulihkan data contoh untuk bereksplorasi kembali, atau mulai dengan inventaris kosong.</p><div class="heading-actions"><button class="button" @click="reset()"><RotateCcw :size="16"/>Reset Data Contoh</button><button class="button danger-button" @click="reset(true)"><Trash2 :size="16"/>Hapus Seluruh Data</button></div></section></div></div>
  </template>
</div>

<Modal v-if="modal==='product'" :title="editing?'Edit Barang':'Tambah Barang'" subtitle="Detail yang rapi membuat inventaris lebih mudah dikelola." @close="modal=''"><form @submit.prevent="submitProduct"><div class="form-grid"><label class="full">Nama barang<input v-model="form.name" required maxlength="120" placeholder="Contoh: Monitor Dell 24 inci"/></label><label>Kode barang<input v-model="form.code" required maxlength="30" placeholder="ELK-001" class="uppercase"/></label><label>Kategori<select v-model="form.categoryId" required><option disabled value="">Pilih kategori</option><option v-for="c in state.data.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Satuan<input v-model="form.unit" required maxlength="20" placeholder="pcs, unit, rim"/></label><label>Minimum stok<input v-model.number="form.minimum" type="number" min="0" step="1" required/></label><label :class="{full:!!editing}">Harga modal (opsional)<input v-model="form.cost" type="number" min="0" max="1000000000000" step="any" placeholder="Rp 0"/></label><label v-if="!editing">Stok awal<input v-model.number="form.initial" type="number" min="0" step="1" required/></label></div><p class="form-hint">{{editing?'Perubahan stok dicatat melalui menu Transaksi Stok.':'Stok awal otomatis dicatat sebagai transaksi masuk hari ini.'}}</p><p v-if="!state.data.categories.length" class="form-error">Buat kategori terlebih dahulu melalui halaman Kategori.</p><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><button type="button" class="button" @click="modal=''">Batal</button><button class="button primary" :disabled="state.busy||!state.data.categories.length">{{state.busy?'Menyimpan…':'Simpan Barang'}}</button></div></form></Modal>
<Modal v-if="modal==='category'" :title="editing?'Edit Kategori':'Tambah Kategori'" @close="modal=''"><form @submit.prevent="submitCategory"><div class="form-grid"><label class="full">Nama kategori<input v-model="categoryForm.name" required maxlength="60" placeholder="Contoh: Elektronik"/></label><label class="full">Warna kategori<input v-model="categoryForm.color" type="color"/></label></div><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><button type="button" class="button" @click="modal=''">Batal</button><button class="button primary" :disabled="state.busy">Simpan Kategori</button></div></form></Modal>
<Modal v-if="modal==='movement'" title="Catat Transaksi Stok" subtitle="Saldo dan histori akan diperbarui secara bersamaan." @close="modal=''"><form @submit.prevent="submitMovement"><div class="segmented"><button type="button" :class="{active:movementForm.type==='in'}" @click="movementForm.type='in'"><ArrowDownLeft :size="17"/>Stok Masuk</button><button type="button" :class="{active:movementForm.type==='out'}" @click="movementForm.type='out'"><ArrowUpRight :size="17"/>Stok Keluar</button></div><div class="form-grid"><label class="full">Barang<select v-model="movementForm.productId" required><option value="" disabled>Pilih barang</option><option v-for="p in activeProducts" :key="p.id" :value="p.id">{{p.code}} — {{p.name}}</option></select></label><div class="stock-preview full"><Package :size="17"/>Stok tersedia<strong>{{activeProducts.find(p=>p.id===movementForm.productId)?.stock??0}} {{activeProducts.find(p=>p.id===movementForm.productId)?.unit}}</strong></div><label>Jumlah<input v-model.number="movementForm.quantity" type="number" min="1" step="1" required/></label><label>Tanggal transaksi<input v-model="movementForm.date" type="date" :max="today()" required/></label><label class="full">Catatan (opsional)<textarea v-model="movementForm.note" rows="3" maxlength="500" placeholder="Sumber penerimaan, tujuan pengeluaran, atau keterangan lain…"></textarea></label></div><p class="form-hint">Transaksi yang sudah dicatat tidak dapat diedit atau dihapus.</p><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><button type="button" class="button" @click="modal=''">Batal</button><button class="button primary" :disabled="state.busy||!activeProducts.length">{{state.busy?'Menyimpan…':'Simpan Transaksi'}}</button></div></form></Modal>
<Modal v-if="modal==='confirm'" :title="confirmTitle" @close="modal=''"><p class="confirm-text">{{confirmText}}</p><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><button class="button" @click="modal=''">Batal</button><button class="button primary" :disabled="state.busy" @click="attempt(confirmAction)">{{state.busy?'Memproses…':'Ya, Lanjutkan'}}</button></div></Modal>
</template>
